import React, { useState, useEffect } from 'react';
import { getLatestMovies } from '../db/tmdb';

function MovieSlider() {
  const [movies, setMovies] = useState([]);
  const [currentIndex, setCurrentIndex] = useState(0);

  useEffect(() => {
    const fetchMovies = async () => {
      const data = await getLatestMovies();
      setMovies(data);
    };
    fetchMovies();
  }, []);

  const handlePrev = () => {
    setCurrentIndex((prev) => (prev === 0 ? movies.length - 1 : prev - 1));
  };

  const handleNext = () => {
    setCurrentIndex((prev) => (prev === movies.length - 1 ? 0 : prev + 1));
  };

  return (
    <div className="main-slider-container">
      {/* 상단 히어로 텍스트 영역 */}
      <div className="hero-text-section">
        <h2>Explore a world where ideas move<br />beyond the screen</h2>
        <p>Spatial thinking used to test clarity and intent before design decisions are locked.</p>
      </div>

      {/* 3D 둥근 아치형 갤러리 영역 */}
      <div className="curved-slider-wrapper">
        <div className="curved-slider-track">
          {movies.map((movie, index) => {
            const offset = (index - currentIndex + movies.length) % movies.length;
            let displayOffset = offset;
            if (offset > movies.length / 2) {
              displayOffset -= movies.length;
            }

            // 💡 시안의 원통형 회전/곡면 물리값 계산
            const angle = displayOffset * 22; // 각도에 따른 회전
            const radius = 380; // 원통의 반지름 크기
            const translateX = Math.sin((angle * Math.PI) / 180) * radius;
            const translateZ = (Math.cos((angle * Math.PI) / 180) - 1) * radius - 50;
            const rotateY = -angle; // 양옆 카드가 안쪽을 바라보도록 꺾이는 각도
            const scale = Math.max(1 - Math.abs(displayOffset) * 0.15, 0.65);
            const opacity = Math.abs(displayOffset) > 2.5 ? 0 : 1;

            return (
              <div
                key={movie.id}
                className={`slider-card ${displayOffset === 0 ? 'active' : ''}`}
                style={{
                  transform: `translateX(${translateX}px) translateZ(${translateZ}px) rotateY(${rotateY}deg) scale(${scale})`,
                  zIndex: movies.length - Math.abs(displayOffset),
                  opacity: opacity,
                  pointerEvents: opacity === 0 ? 'none' : 'auto',
                }}
                onClick={() => setCurrentIndex(index)}
              >
                <img
                  src={`https://image.tmdb.org/t/p/w500${movie.poster_path}`}
                  alt={movie.title}
                />
              </div>
            );
          })}
        </div>
      </div>

      {/* 좌우 네비게이션 컨트롤 버튼 */}
      <div className="slider-controls">
        <button className="slider-arrow" onClick={handlePrev}>&larr;</button>
        <button className="slider-arrow" onClick={handleNext}>&rarr;</button>
      </div>
    </div>
  );
}

export default MovieSlider;
